    def __enter__(self): return self
    def __exit__(self, *args): return False
    def getcode(self): return 200
    def read(self):
        return json.dumps({
            'id': 'resp_test',
            'model': 'test-model',
            'status': 'completed',
            'output': [
                {'type': 'message', 'role': 'assistant', 'content': [
                    {'type': 'output_text', 'text': 'Private '}
                ]},
                {'type': 'message', 'role': 'assistant', 'content': [
                    {'type': 'output_text', 'text': 'answer.'}
                ]}
            ],
            'usage': {'input_tokens': 2, 'output_tokens': 3},
        }).encode()

def fake_urlopen(request, timeout):
    captured['url'] = request.full_url
    captured['method'] = request.method
    captured['headers'] = dict(request.header_items())
    captured['body'] = json.loads(request.data.decode())
    captured['timeout'] = timeout
    return FakeResponse()

with patch('urllib.request.urlopen', side_effect=fake_urlopen):
    client = openai_client.OpenAIClient(
        api_key='[REDACTED_SECRET]', base_url='https://example.test', model='test-model',
        timeout=12
    )
    response = client.send_prompt('Do not persist this.', max_output_tokens=50)

assert captured['url'] == 'https://example.test/v1/responses'
assert captured['method'] == 'POST'
assert captured['headers']['Authorization'] == 'Bearer secret-test-key'
assert captured['body']['input'] == 'Do not persist this.'
assert captured['body']['model'] == 'test-model'
assert captured['body']['store'] is False
assert captured['body']['stream'] is False
assert captured['body']['max_output_tokens'] == 50
assert response.text == 'Private answer.'
assert response.id == 'resp_test'
assert response.usage['output_tokens'] == 3

for kwargs in ({'store': True}, {'stream': True}):
    try:
        client.create_response('x', **kwargs)
    except ValueError:
        pass
    else:
        raise AssertionError(kwargs)

headers = Message()
headers['Retry-After'] = '0'
http_error = urllib.error.HTTPError(
    'https://example.test/v1/responses', 429, 'Too Many Requests', headers,
    body=None, fp=None,
)
calls = {'n': 0}
def fail_once(*args, **kwargs):
    calls['n'] += 1
    if calls['n'] == 1:
        raise http_error
    return FakeResponse()

with patch('urllib.request.urlopen', side_effect=fail_once), patch('time.sleep') as sleep:
    result = client.create_response('x')
assert result['status'] == 'completed'
assert calls['n'] == 2
sleep.assert_called_once_with(0.0)

print('validation: ok')
